class ThemeManager{constructor(){this.currentTheme=localStorage.getItem("theme")||"light",this.init()}init(){this.applyTheme(this.currentTheme)}applyTheme(e){document.documentElement.setAttribute("data-theme",e),this.currentTheme=e,localStorage.setItem("theme",e)}toggle(){const e="light"===this.currentTheme?"dark":"light";return this.applyTheme(e),e}getTheme(){return this.currentTheme}}window.themeManager=new ThemeManager;